3	namespace App\Http\Controllers\Api\Webhooks;
4	
5	use App\Http\Controllers\Controller;
6	use App\Models\Billing\Plan;
7	use App\Models\Billing\Subscription;
8	use App\Models\Core\Professional\Professional;
9	use App\Services\Notifications\NotificationPublisher;
10	use App\Services\Professional\SiteProvisioningService;
11	use Carbon\Carbon;
12	use Illuminate\Http\JsonResponse;
13	use Illuminate\Http\Request;
14	use Illuminate\Support\Facades\DB;
15	use Illuminate\Support\Facades\Log;
16	use Illuminate\Support\Str;
17	use Stripe\Exception\SignatureVerificationException;
18	use Stripe\Webhook;
19	
20	// V2: Core. Processes Stripe Billing subscription lifecycle webhooks. Source of truth for subscription state.
21	class StripeWebhookController extends Controller
22	{
23	    public function __invoke(Request $request): JsonResponse
24	    {
25	        $payload = $request->getContent();
26	        $sigHeader = $request->header('Stripe-Signature');
27	
28	        if (! $sigHeader) {
29	            return response()->json(['error' => 'Missing signature'], 400);
30	        }
31	
32	        $secret = config('services.stripe.webhook_secret');
33	
34	        if (! $secret) {
35	            return response()->json(['error' => 'No webhook secret configured'], 400);
36	        }
37	
38	        try {
39	            $event = Webhook::constructEvent($payload, $sigHeader, $secret);
40	        } catch (SignatureVerificationException) {
41	            Log::warning('Stripe billing webhook signature verification failed');
42	
43	            return response()->json(['error' => 'Invalid signature'], 400);
44	        } catch (\Exception $e) {
45	            Log::warning('Stripe billing webhook parse error', ['error' => $e->getMessage()]);
46	
47	            return response()->json(['error' => 'Invalid payload'], 400);
48	        }
49	
50	        // Idempotency: atomic insert-or-skip using DB unique constraint on stripe_event_id.
51	        // This prevents race conditions where two concurrent requests pass an exists() check.
52	        $alreadyProcessed = ! DB::table('billing.webhook_events')->insertOrIgnore([
53	            'id' => Str::uuid()->toString(),
54	            'stripe_event_id' => $event->id,
55	            'event_type' => $event->type,
56	            'payload' => json_encode(json_decode($payload, true)),
57	            'processed_at' => now(),
58	        ]);
59	
60	        if ($alreadyProcessed) {
61	            return response()->json(['received' => true]);
62	        }
63	
64	        match ($event->type) {
65	            'customer.subscription.created' => $this->handleSubscriptionCreated($event->data->object, $event),
66	            'customer.subscription.updated' => $this->handleSubscriptionUpdated($event->data->object, $event),
67	            'customer.subscription.deleted' => $this->handleSubscriptionDeleted($event->data->object, $event),
68	            'invoice.paid' => $this->handleInvoicePaid($event->data->object, $event),
69	            'invoice.payment_failed' => $this->handleInvoicePaymentFailed($event->data->object, $event),
70	            default => Log::debug('Unhandled Stripe billing event', ['type' => $event->type]),
71	        };
72	
73	        return response()->json(['received' => true]);
74	    }
75	
76	    private function handleSubscriptionCreated(object $subscription, object $event): void
77	    {
78	        // Resolve professional: prefer stripe_customer_id lookup (tamper-proof),
79	        // fall back to metadata (set server-side by StripeBillingService).
80	        $stripeCustomerId = (string) ($subscription->customer ?? '');
81	        $professional = $stripeCustomerId
82	            ? Professional::where('stripe_customer_id', $stripeCustomerId)->first()
83	            : null;
84	
85	        if (! $professional) {
86	            $professionalId = $subscription->metadata?->sidest_professional_id ?? null;
87	            $professional = $professionalId ? Professional::find($professionalId) : null;
88	        }
89	
90	        if (! $professional) {
91	            Log::warning('Stripe subscription.created: could not resolve professional', [
92	                'subscription_id' => $subscription->id,
93	                'customer_id' => $stripeCustomerId,
94	                'metadata_professional_id' => $subscription->metadata?->sidest_professional_id ?? null,
95	            ]);
96	
97	            return;
98	        }
99	
100	        $priceId = $subscription->items->data[0]->price->id ?? null;
101	        $plan = Plan::where('stripe_price_id', $priceId)->where('is_active', true)->first();
102	
103	        if (! $plan) {
104	            Log::error('Stripe subscription.created with unknown price — customer charged but no local subscription created. Manual reconciliation required.', [
105	                'price_id' => $priceId,
106	                'professional_id' => $professional->id,
107	                'stripe_subscription_id' => $subscription->id,
108	            ]);
109	
110	            return;
111	        }
112	
113	        DB::transaction(function () use ($professional, $plan, $subscription, $event) {
114	            // End any existing active subscription (lockForUpdate prevents deadlocks)
115	            Subscription::query()
116	                ->where('professional_id', $professional->id)
117	                ->whereNull('ended_at')
118	                ->lockForUpdate()
119	                ->update(['ended_at' => now()]);
120	
121	            // Create the new Stripe-managed subscription; stripe IDs set directly (not mass-assignable)
122	            $localSub = new Subscription([
123	                'id' => Str::uuid()->toString(),
124	                'professional_id' => $professional->id,
125	                'plan_id' => $plan->id,
126	                'provider' => 'stripe',
127	                'status' => $this->mapStripeStatus($subscription->status),
128	                'current_period_start' => Carbon::createFromTimestamp($subscription->current_period_start),
129	                'current_period_end' => Carbon::createFromTimestamp($subscription->current_period_end),
130	                'cancel_at_period_end' => $subscription->cancel_at_period_end ?? false,
131	                'provider_payload' => json_decode(json_encode($event), true),
132	            ]);
133	            $localSub->stripe_customer_id = (string) $subscription->customer;
134	            $localSub->stripe_subscription_id = (string) $subscription->id;
135	            $localSub->save();
136	        });
137	
138	        Log::info('Stripe subscription created', [
139	            'professional_id' => $professional->id,
140	            'plan_key' => $plan->plan_key,
141	            'stripe_subscription_id' => $subscription->id,
142	        ]);
143	    }
144	
145	    private function handleSubscriptionUpdated(object $subscription, object $event): void
146	    {
147	        $localSub = Subscription::where('stripe_subscription_id', $subscription->id)->first();
148	
149	        if (! $localSub) {
150	            Log::debug('Stripe subscription.updated for unknown subscription', [
151	                'stripe_subscription_id' => $subscription->id,
152	            ]);
153	
154	            return;
155	        }
156	
157	        $updates = [
158	            'status' => $this->mapStripeStatus($subscription->status),
159	            'current_period_start' => Carbon::createFromTimestamp($subscription->current_period_start),
160	            'current_period_end' => Carbon::createFromTimestamp($subscription->current_period_end),
161	            'cancel_at_period_end' => $subscription->cancel_at_period_end ?? false,
162	            'provider_payload' => json_decode(json_encode($event), true),
163	        ];
164	
165	        // Check if price changed (plan upgrade/downgrade)
166	        $priceId = $subscription->items->data[0]->price->id ?? null;
167	        if ($priceId) {
168	            $plan = Plan::where('stripe_price_id', $priceId)->where('is_active', true)->first();
169	            if ($plan && $plan->id !== $localSub->plan_id) {
170	                $updates['plan_id'] = $plan->id;
171	            }
172	        }
173	
174	        $localSub->update($updates);
175	
176	        Log::info('Stripe subscription updated', [
177	            'subscription_id' => $localSub->id,
178	            'status' => $updates['status'],
179	        ]);
180	    }
181	
182	    private function handleSubscriptionDeleted(object $subscription, object $event): void
183	    {
184	        $localSub = Subscription::where('stripe_subscription_id', $subscription->id)->first();
185	
186	        if (! $localSub) {
187	            Log::debug('Stripe subscription.deleted for unknown subscription', [
188	                'stripe_subscription_id' => $subscription->id,
189	            ]);
190	
191	            return;
192	        }
193	
194	        $localSub->update([
195	            'status' => Subscription::STATUS_CANCELED,
196	            'ended_at' => now(),
197	            'provider_payload' => json_decode(json_encode($event), true),
198	        ]);
199	
200	        // For affiliates, fall back to free plan. Brands do NOT get a free fallback.
201	        $professional = $localSub->professional;
202	        if ($professional && $professional->professional_type !== 'brand') {
203	            app(SiteProvisioningService::class)->ensureFreeSubscription($professional);
204	        }
205	
206	        Log::info('Stripe subscription deleted', [
207	            'subscription_id' => $localSub->id,
208	            'professional_id' => $localSub->professional_id,
209	            'fallback_to_free' => $professional?->professional_type !== 'brand',
210	        ]);
211	    }
212	
213	    private function handleInvoicePaid(object $invoice, object $event): void
214	    {
215	        $stripeSubId = $invoice->subscription ?? null;
216	        if (! $stripeSubId) {
217	            return;
218	        }
219	
220	        $localSub = Subscription::where('stripe_subscription_id', $stripeSubId)->first();
221	        if (! $localSub) {
222	            return;
223	        }
224	
225	        $updates = [
226	            'provider_payload' => json_decode(json_encode($event), true),
227	        ];
228	
229	        // Reset to active if was past_due (successful retry)
230	        if ($localSub->status === Subscription::STATUS_PAST_DUE) {
231	            $updates['status'] = Subscription::STATUS_ACTIVE;
232	        }
233	
234	        // Update period dates from invoice
235	        if (isset($invoice->lines->data[0]->period)) {
236	            $period = $invoice->lines->data[0]->period;
237	            $updates['current_period_start'] = Carbon::createFromTimestamp($period->start);
238	            $updates['current_period_end'] = Carbon::createFromTimestamp($period->end);
239	        }
240	
241	        $localSub->update($updates);
242	
243	        Log::info('Stripe invoice paid', [
244	            'subscription_id' => $localSub->id,
245	            'status' => $localSub->fresh()->status,
246	        ]);
247	    }
248	
249	    private function handleInvoicePaymentFailed(object $invoice, object $event): void
250	    {
251	        $stripeSubId = $invoice->subscription ?? null;
252	        if (! $stripeSubId) {
253	            return;
254	        }
255	
256	        $localSub = Subscription::where('stripe_subscription_id', $stripeSubId)->first();
257	        if (! $localSub) {
258	            return;
259	        }
260	
261	        $localSub->update([
262	            'status' => Subscription::STATUS_PAST_DUE,
263	            'provider_payload' => json_decode(json_encode($event), true),
264	        ]);
265	
266	        // Notify the professional about the payment failure
267	        $professional = $localSub->professional;
268	        if ($professional) {
269	            app(NotificationPublisher::class)->publish(
270	                professionalId: $professional->id,
271	                frontendType: 'warning',
272	                category: 'subscriptions',
273	                title: 'Payment failed',
274	                body: 'Your subscription payment could not be processed. Please update your payment method to avoid service interruption.',
275	                dedupeKey: 'payment-failed-'.$localSub->id.'-'.now()->format('Y-m-d'),
276	                ctaUrl: '/account/billing',
277	                primaryActionLabel: 'Update Payment',
278	            );
279	        }
280	
281	        Log::warning('Stripe invoice payment failed', [
282	            'subscription_id' => $localSub->id,
283	            'professional_id' => $localSub->professional_id,
284	        ]);
285	    }
286	
287	    private function mapStripeStatus(string $stripeStatus): string
288	    {
289	        return match ($stripeStatus) {
290	            'active' => Subscription::STATUS_ACTIVE,
291	            'past_due' => Subscription::STATUS_PAST_DUE,
292	            'unpaid' => Subscription::STATUS_UNPAID,
293	            'canceled' => Subscription::STATUS_CANCELED,
294	            'incomplete' => Subscription::STATUS_INCOMPLETE,
295	            'incomplete_expired' => Subscription::STATUS_INCOMPLETE_EXPIRED,
296	            'trialing' => Subscription::STATUS_ACTIVE, // we don't use trials — map to active
297	            'paused' => Subscription::STATUS_PAUSED,
298	            default => $stripeStatus,
299	        };
300	    }
301	}
