16	use Stripe\Webhook;
17	
18	// V2: Core. Processes Stripe Connect events: account updates, checkout completions, transfer status, payment intents. Drives the commission payout lifecycle.
19	class StripeConnectWebhookController extends Controller
20	{
21	    public function __invoke(Request $request): JsonResponse
22	    {
23	        $payload = $request->getContent();
24	        $sigHeader = $request->header('Stripe-Signature');
25	
26	        if (! $sigHeader) {
27	            return response()->json(['error' => 'Missing signature'], 400);
28	        }
29	
30	        // Try both Connect and platform webhook secrets so one endpoint URL
31	        // can handle events from connected accounts and destination charges.
32	        $secrets = array_filter([
33	            config('services.stripe.connect_webhook_secret'),
34	            config('services.stripe.webhook_secret'),
35	        ]);
36	
37	        if ($secrets === []) {
38	            return response()->json(['error' => 'No webhook secret configured'], 400);
39	        }
40	
41	        $event = null;
42	        foreach ($secrets as $secret) {
43	            try {
44	                $event = Webhook::constructEvent($payload, $sigHeader, $secret);
45	                break;
46	            } catch (SignatureVerificationException) {
47	                continue;
48	            } catch (\Exception $e) {
49	                Log::warning('Stripe webhook parse error', ['error' => $e->getMessage()]);
50	
51	                return response()->json(['error' => 'Invalid payload'], 400);
52	            }
53	        }
54	
55	        if (! $event) {
56	            Log::warning('Stripe webhook signature verification failed for all configured secrets');
57	
58	            return response()->json(['error' => 'Invalid signature'], 400);
59	        }
60	
61	        // Idempotency: atomic insert-or-skip on the UNIQUE stripe_event_id.
62	        // Stripe event IDs are globally unique across platform + Connect events,
63	        // so billing.webhook_events covers both this controller and StripeWebhookController.
64	        // The insert is committed before the match() dispatch: if a handler throws a 500,
65	        // Stripe's retry will see the existing row and be short-circuited here rather than
66	        // re-triggering the crashing handler. Investigate via Nightwatch if that occurs.
67	        $alreadyProcessed = ! DB::table('billing.webhook_events')->insertOrIgnore([
68	            'id' => Str::uuid()->toString(),
69	            'stripe_event_id' => $event->id,
70	            'event_type' => $event->type,
71	            'payload' => json_encode(json_decode($payload, true)),
72	            'processed_at' => now(),
73	        ]);
74	
75	        if ($alreadyProcessed) {
76	            return response()->json(['received' => true]);
77	        }
78	
79	        return $this->handleParsedEvent($event);
80	    }
81	
82	    /**
83	     * Dispatch a verified, de-duplicated Stripe Event to the appropriate handler.
84	     * Extracted from __invoke() so it can be unit-tested without HMAC signing.
85	     *
86	     * Guards account-scoped event types by verifying the HMAC-signed top-level
87	     * `event->account` field matches `data.object->id`. A mismatch means the
88	     * payload was tampered with; we reject with 400 rather than mutating records.
89	     */
90	    public function handleParsedEvent(\Stripe\Event $event): JsonResponse
91	    {
92	        // For account-scoped events, event->account is the HMAC-signed source of truth.
93	        // If data.object.id differs, reject — payload could have been tampered with
94	        // to mutate a victim account using the attacker's valid HMAC.
95	        //
96	        // account.application.* events are excluded: their data.object is an Application
97	        // (id = ca_xxx), not an Account, so the id won't match event->account by design.
98	        $accountScopedPrefixes = ['account.', 'capability.'];
99	        $isAccountScoped = collect($accountScopedPrefixes)
100	            ->contains(fn ($p) => str_starts_with($event->type, $p));
101	
102	        if ($isAccountScoped && ! str_starts_with($event->type, 'account.application.')) {
103	            $topLevelAccount = $event->account ?? null;
104	            $objectId = $event->data->object->id ?? null;
105	
106	            if ($topLevelAccount === null || $topLevelAccount !== $objectId) {
107	                Log::warning('stripe.connect.account_mismatch', [
108	                    'event_id' => $event->id,
109	                    'event_account' => $topLevelAccount,
110	                    'object_id' => $objectId,
111	                ]);
112	
113	                return response()->json(['error' => 'account_mismatch'], 400);
114	            }
115	        }
116	
117	        match ($event->type) {
118	            'account.updated' => $this->handleAccountUpdated($event->data->object),
119	            'account.application.deauthorized' => $this->handleAccountDeauthorized((string) ($event->account ?? '')),
120	            'checkout.session.completed' => $this->handleCheckoutSessionCompleted($event->data->object, (string) ($event->account ?? '')),
121	            'transfer.created' => $this->handleTransferCreated($event->data->object),
122	            'transfer.failed' => $this->handleTransferFailed($event->data->object),
123	            'transfer.reversed' => $this->handleTransferFailed($event->data->object),
124	            'payment_intent.succeeded' => $this->handlePaymentIntentSucceeded($event->data->object, (string) ($event->account ?? '')),
125	            'payment_intent.payment_failed' => $this->handlePaymentIntentFailed($event->data->object),
126	            default => Log::debug('Unhandled Stripe Connect event', ['type' => $event->type]),
127	        };
128	
129	        return response()->json(['received' => true]);
130	    }
131	
132	    private function handleCheckoutSessionCompleted(object $checkoutSession, string $connectedAccountId): void
133	    {
134	        Log::debug('Stripe checkout session completed (no-op in V2)', [
135	            'checkout_session_id' => $checkoutSession->id ?? null,
136	            'connected_account_id' => $connectedAccountId,
137	        ]);
138	    }
139	
140	    /**
141	     * Handle account.application.deauthorized — fired when an Express account owner
142	     * revokes access via their Stripe dashboard. Mark them disconnected locally so
143	     * the payout job stops targeting their account and the UI surfaces the disconnect.
144	     *
145	     * Note: event->account is the connected account ID (HMAC-signed); event->data->object
146	     * is an Application object whose id will differ. The account-scope guard is skipped
147	     * for account.application.* events for this reason.
148	     */
149	    private function handleAccountDeauthorized(string $stripeAccountId): void
150	    {
151	        if (! $stripeAccountId) {
152	            Log::warning('stripe.connect.deauthorize_missing_account');
153	
154	            return;
155	        }
156	
157	        $professional = Professional::where('stripe_connect_account_id', $stripeAccountId)->first();
158	
159	        if (! $professional) {
160	            Log::debug('Stripe account.application.deauthorized for unknown account', ['account_id' => $stripeAccountId]);
161	
162	            return;
163	        }
164	
165	        $professional->update(['stripe_connect_status' => 'disconnected']);
166	
167	        Log::info('Stripe Connect account deauthorized via dashboard', [
168	            'professional_id' => $professional->id,
169	            'account_id' => $stripeAccountId,
170	        ]);
171	    }
172	
173	    private function handleAccountUpdated(object $account): void
174	    {
175	        $professional = Professional::where('stripe_connect_account_id', $account->id)->first();
176	
177	        if (! $professional) {
178	            Log::debug('Stripe account.updated for unknown account', ['account_id' => $account->id]);
179	
180	            return;
181	        }
182	
183	        // Respect local disconnect: if the professional has soft-disconnected
184	        // the account, ignore incoming Stripe events until they explicitly
185	        // reconnect via createOnboardingLink. Prevents a late account.updated
186	        // event from silently re-activating a disconnected account.
187	        if ($professional->stripe_connect_status === 'disconnected') {
188	            Log::debug('Stripe account.updated skipped — account locally disconnected', [
189	                'professional_id' => $professional->id,
190	                'account_id' => $account->id,
191	            ]);
192	
193	            return;
194	        }
195	
196	        $status = StripeConnectService::determineAccountStatus($account);
197	
198	        if ($professional->stripe_connect_status !== $status) {
199	            $oldStatus = $professional->stripe_connect_status;
200	
201	            // Atomic: if flushHeldCommissions throws, the status update is rolled back.
202	            // The professional stays in their prior state; the next account.updated
203	            // (new event_id, bypasses idempotency) retries the full transition cleanly.
204	            DB::transaction(function () use ($professional, $status, $oldStatus) {
205	                $professional->update(['stripe_connect_status' => $status]);
206	
207	                // When an affiliate transitions to 'active', flush any held commissions
208	                // so they enter the normal payout pipeline immediately.
209	                if ($status === 'active' && $oldStatus !== 'active') {
210	                    app(CommissionVoidService::class)->flushHeldCommissions($professional);
211	                }
212	            });
213	
214	            Log::info('Stripe Connect status updated', [
215	                'professional_id' => $professional->id,
216	                'old_status' => $oldStatus,
217	                'new_status' => $status,
218	            ]);
219	        }
220	    }
221	
222	    private function handleTransferCreated(object $transfer): void
223	    {
224	        $payoutId = $transfer->metadata?->sidest_payout_id ?? null;
225	
226	        if (! $payoutId) {
227	            return;
228	        }
229	
230	        Log::info('Stripe transfer created', [
231	            'transfer_id' => $transfer->id,
232	            'payout_id' => $payoutId,
233	        ]);
234	    }
235	
236	    private function handleTransferFailed(object $transfer): void
237	    {
238	        $payoutId = $transfer->metadata?->sidest_payout_id ?? null;
239	
240	        if (! $payoutId) {
241	            return;
242	        }
243	
244	        $payout = CommissionPayout::find($payoutId);
245	        if ($payout && ! in_array($payout->status, ['failed', 'completed', 'cancelled'], true)) {
246	            $payout->forceFill([
247	                'status' => 'failed',
248	                'failure_code' => 'transfer_failed_webhook',
249	                'failure_reason' => 'Transfer failed according to Stripe webhook',
250	            ])->save();
251	        }
252	
253	        Log::warning('Stripe transfer failed', [
254	            'transfer_id' => $transfer->id,
255	            'payout_id' => $payoutId,
256	        ]);
257	    }
258	
259	    private function handlePaymentIntentSucceeded(object $paymentIntent, string $connectedAccountId = ''): void
260	    {
261	        // Commission payout payment intent
262	        $payoutId = $paymentIntent->metadata?->sidest_payout_id ?? null;
263	        if (! $payoutId) {
264	            return;
265	        }
266	
267	        Log::info('Stripe payment intent succeeded for payout', [
268	            'payment_intent_id' => $paymentIntent->id,
269	            'payout_id' => $payoutId,
270	        ]);
271	    }
272	
273	    private function handlePaymentIntentFailed(object $paymentIntent): void
274	    {
275	        $payoutId = $paymentIntent->metadata?->sidest_payout_id ?? null;
276	
277	        if (! $payoutId) {
278	            return;
279	        }
280	
281	        $payout = CommissionPayout::find($payoutId);
282	        if ($payout && ! in_array($payout->status, ['failed', 'completed'])) {
283	            $payout->forceFill([
284	                'status' => 'failed',
285	                'failure_code' => 'payment_failed_webhook',
286	                'failure_reason' => $paymentIntent->last_payment_error?->message ?? 'Payment failed',
287	            ])->save();
288	        }
289	
290	        Log::warning('Stripe payment intent failed for payout', [
291	            'payment_intent_id' => $paymentIntent->id,
292	            'payout_id' => $payoutId,
293	        ]);
294	    }
295	}
