76	    private function handleSubscriptionCreated(object $subscription, object $event): void
77	    {
78	        // Resolve professional: prefer stripe_customer_id lookup (tamper-proof),
79	        // fall back to metadata (set server-side by StripeBillingService).
80	        $stripeCustomerId = (string) ($subscription->customer ?? '');
81	        $professional = $stripeCustomerId
82	            ? Professional::where('stripe_customer_id', $stripeCustomerId)->first()
83	            : null;
84	
85	        if (! $professional) {
86	            $professionalId = $subscription->metadata?->sidest_professional_id ?? null;
87	            $professional = $professionalId ? Professional::find($professionalId) : null;
88	        }
89	
90	        if (! $professional) {
91	            Log::warning('Stripe subscription.created: could not resolve professional', [
92	                'subscription_id' => $subscription->id,
93	                'customer_id' => $stripeCustomerId,
94	                'metadata_professional_id' => $subscription->metadata?->sidest_professional_id ?? null,
95	            ]);
96	
97	            return;
98	        }
99	
100	        $priceId = $subscription->items->data[0]->price->id ?? null;
101	        $plan = Plan::where('stripe_price_id', $priceId)->where('is_active', true)->first();
102	
103	        if (! $plan) {
104	            Log::error('Stripe subscription.created with unknown price — customer charged but no local subscription created. Manual reconciliation required.', [
105	                'price_id' => $priceId,
106	                'professional_id' => $professional->id,
107	                'stripe_subscription_id' => $subscription->id,
108	            ]);
109	
110	            return;
111	        }
112	
113	        DB::transaction(function () use ($professional, $plan, $subscription, $event) {
114	            // End any existing active subscription (lockForUpdate prevents deadlocks)
115	            Subscription::query()
116	                ->where('professional_id', $professional->id)
117	                ->whereNull('ended_at')
118	                ->lockForUpdate()
119	                ->update(['ended_at' => now()]);
120	
121	            // Create the new Stripe-managed subscription; stripe IDs set directly (not mass-assignable)
122	            $localSub = new Subscription([
123	                'id' => Str::uuid()->toString(),
124	                'professional_id' => $professional->id,
125	                'plan_id' => $plan->id,
126	                'provider' => 'stripe',
127	                'status' => $this->mapStripeStatus($subscription->status),
128	                'current_period_start' => Carbon::createFromTimestamp($subscription->current_period_start),
129	                'current_period_end' => Carbon::createFromTimestamp($subscription->current_period_end),
130	                'cancel_at_period_end' => $subscription->cancel_at_period_end ?? false,
131	                'provider_payload' => json_decode(json_encode($event), true),
132	            ]);
133	            $localSub->stripe_customer_id = (string) $subscription->customer;
134	            $localSub->stripe_subscription_id = (string) $subscription->id;
135	            $localSub->save();
136	        });
137	
138	        Log::info('Stripe subscription created', [
139	            'professional_id' => $professional->id,
140	            'plan_key' => $plan->plan_key,
141	            'stripe_subscription_id' => $subscription->id,
142	        ]);
143	    }
